"""Read ids.txt and print the next order id."""

ALPHABET = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ"


def decode(s: str) -> int:
    """Convert a base-32 string to an integer."""
    n = 0
    for ch in s:
        n = n * 32 + ALPHABET.index(ch)
    return n


def encode(n: int, width: int = 4) -> str:
    """Convert an integer to a zero-padded base-32 string."""
    chars = []
    for _ in range(width):
        chars.append(ALPHABET[n % 32])
        n //= 32
    return "".join(reversed(chars))


def main() -> None:
    with open("ids.txt") as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        # No ids yet — start from zero
        suffix = encode(0)
    else:
        last_id = lines[-1]
        suffix = last_id.split("-")[1]
        n = decode(suffix)
        suffix = encode(n + 1)

    print(f"ORD-{suffix}")


if __name__ == "__main__":
    main()

