import sys

BASE36_ALPHABET = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def base36_decode(s: str) -> int:
    value = 0
    for char in s:
        value = value * 36 + BASE36_ALPHABET.index(char.upper())
    return value


def base36_encode(value: int, width: int) -> str:
    chars = []
    while value > 0:
        chars.append(BASE36_ALPHABET[value % 36])
        value //= 36
    encoded = ''.join(reversed(chars))
    return encoded.rjust(width, '0')


def next_id(last_id: str) -> str:
    prefix, suffix = last_id.split('-')
    num = base36_decode(suffix)
    next_num = num + 1
    next_suffix = base36_encode(next_num, len(suffix))
    return f'{prefix}-{next_suffix}'


def main():
    try:
        with open('ids.txt') as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print('ids.txt not found in current directory', file=sys.stderr)
        sys.exit(1)

    if not lines:
        print('ids.txt is empty', file=sys.stderr)
        sys.exit(1)

    last_id = lines[-1]
    print(next_id(last_id))


if __name__ == '__main__':
    main()
