#!/usr/bin/env python3
"""Read ids.txt (one order id per line, most recent last) and print the next order id."""

import sys

def base36_encode(n: int, width: int = 4) -> str:
    """Encode integer n as a zero-padded base36 string of given width."""
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = []
    for _ in range(width):
        result.append(chars[n % 36])
        n //= 36
    if n != 0:
        raise ValueError(f"Number too large for width {width}")
    return "".join(reversed(result))

def base36_decode(s: str) -> int:
    """Decode a base36 string to an integer."""
    return int(s, 36)

def main():
    try:
        with open("ids.txt", "r") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-0000")
        return

    if not lines:
        print("ORD-0000")
        return

    last_id = lines[-1]
    if not last_id.startswith("ORD-"):
        print(f"Error: unexpected id format: {last_id}", file=sys.stderr)
        sys.exit(1)

    suffix = last_id[4:]
    n = base36_decode(suffix)
    next_suffix = base36_encode(n + 1)
    print(f"ORD-{next_suffix}")

if __name__ == "__main__":
    main()

