#!/usr/bin/env python3
"""Read attendees.txt, sort casefold + accent-insensitive, write roster.txt."""

import unicodedata


def sort_key(name: str) -> str:
    """Casefold and strip accents for sorting."""
    folded = name.casefold()
    # Decompose and remove combining diacritical marks
    decomposed = unicodedata.normalize("NFD", folded)
