"""Read events.jsonl, deduplicate by event_id (keeping last occurrence), write deduped.jsonl."""

import json

def main():
    seen = {}
    with open("events.jsonl") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            seen[event["event_id"]] = event  # overwrite keeps the last occurrence

    with open("deduped.jsonl", "w") as f:
        for event in seen.values():
            f.write(json.dumps(event, separators=(",", ":")) + "\n")

if __name__ == "__main__":
    main()

