import glob
import os

measurements = []

for filepath in glob.glob("inbox/*.txt"):
    with open(filepath) as f:
        for line in f:
            stripped = line.strip()
            if not stripped:
                continue
            parts = stripped.split()
            if len(parts) >= 2:
                try:
                    measurements.append(int(parts[1]))
                except ValueError:
                    pass
            else:
                try:
                    measurements.append(int(parts[0]))
                except ValueError:
                    pass

entries = len(measurements)
total = sum(measurements)
average = total / entries if entries > 0 else 0

with open("report.txt", "w") as f:
    f.write(f"entries {entries}\n")
    f.write(f"total {total}\n")
    f.write(f"average {average:.2f}\n")

